def head(input_file, num_lines=10, output_file=None):
    reader = open(input_file, 'r')

    if output_file is not None:
        writer = open(output_file, 'w')

    for i in range(num_lines):
        line = reader.readline()

        if output_file is not None:
            writer.write(line)
        else:
            print(line, end='')

    reader.close()
    if output_file is not None:
        writer.close()

